//! THE POSITION — what is actually held and actually owed, as of a date coverage really reaches.
//!
//! Ported from `@/features/finance/lib/position`, with one improvement the TypeScript could not
//! make: it reads the ACCOUNT REGISTRY directly rather than a parallel declaration type, so
//! `bsc fin account` feeds this and there is one description of an account rather than two.
//!
//! This is the first capability that takes a [`ReconciledLedger`], and taking one is the point: a
//! position computed from an unchecked transaction list is a confident number built on a list that
//! might be missing a month. The compiler is what stops that.
//!
//! # The sign contract is the whole module
//!
//! A chequing statement printing "1,200.00" means you HAVE $1,200. A card statement printing
//! "2,431.07" means you OWE $2,431.07. Adding the two printed numbers gives $3,631.07, which is not
//! a quantity that exists — the truth is −$1,231.07. So every balance here is SIGNED by what it
//! contributes to net worth, and [`from_statement_balance`] is the one named place a printed figure
//! is converted. Nothing here guesses which convention a number arrived in.
//!
//! The proof the contract holds is that a payment from chequing to a card MOVES NOTHING: −$300 on
//! one account and +$300 on the other, net worth unchanged. Same money, different place — and a
//! model that reports otherwise is wrong in a way that feels like progress.
use crate::account::{Account, Kind};
use crate::money::{money, scale, sum, Currency, Money, Rounding};
use crate::reconcile::ReconciledLedger;

pub use from_statement_balance::from_statement_balance;
pub(crate) use apr_of::apr_of;
pub(crate) use round3::round3;
pub use annual_interest_cost::annual_interest_cost;
pub use overall_utilisation::overall_utilisation;
pub use by_cost::by_cost;

/// A balance as of a date, SIGNED by contribution to net worth.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AccountBalance {
    pub account: String,
    /// `YYYY-MM-DD` the balance was true on.
    pub as_of: String,
    /// Build it with [`from_statement_balance`] rather than by hand.
    pub balance: Money,
}

#[derive(Debug, Clone, PartialEq)]
pub struct AccountPosition {
    pub account: String,
    pub institution: String,
    pub kind: Kind,
    /// Signed, rolled forward from the stated balance to `as_of`.
    pub balance: Money,
    pub as_of: String,
    /// How many transactions were applied on top of the stated balance to get here.
    pub rolled_forward: usize,
    pub is_debt: bool,
    /// POSITIVE amount owed. Present only when the account is actually in debt.
    pub owed: Option<Money>,
    pub credit_limit: Option<Money>,
    pub available: Option<Money>,
    /// 0-1. NONE when the limit is unknown — 0 would read as "nothing used", which is the opposite
    /// of not knowing.
    pub utilisation: Option<f64>,
    /// Annual rate as a fraction: 0.2499 for 24.99%.
    pub apr: Option<f64>,
    /// What this debt costs per day at its rate. The number that makes a balance feel like a bill.
    pub daily_interest: Option<Money>,
    pub minimum_payment: Option<Money>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Position {
    /// The date this is true as of — the ledger's coverage, never later.
    pub as_of: String,
    pub currency: Currency,
    pub accounts: Vec<AccountPosition>,
    /// Assets minus debts. The one number, and it is signed.
    pub net_worth: Money,
    /// What could pay a bill this week — chequing and savings only.
    pub liquid: Money,
    /// POSITIVE total owed across every debt.
    pub total_debt: Money,
    pub daily_interest: Money,
    pub minimums_due: Money,
    /// Balance-weighted APR across debts whose rate is known. None when none is.
    pub weighted_apr: Option<f64>,
    /// False when anything below is standing on something unchecked or unknown.
    pub complete: bool,
    pub problems: Vec<String>,
    pub provenance: String,
}

pub fn position(
    ledger: &ReconciledLedger,
    accounts: &[Account],
    balances: &[AccountBalance],
    currency: Currency,
) -> Position {
    let mut problems: Vec<String> = Vec::new();
    let rows = ledger.covered();

    // AN UNDECLARED ACCOUNT IS NOT A ROUNDING ERROR. Without its kind there is no way to know
    // whether its transactions are money you have or money you owe, and folding it in either way
    // invents a sign. It is named and left out.
    let known: Vec<&str> = accounts.iter().map(|a| a.id.as_str()).collect();
    let mut seen: Vec<&str> = rows.iter().map(|t| t.account.as_str()).collect();
    seen.sort();
    seen.dedup();
    for s in seen {
        if !known.contains(&s) {
            problems.push(format!(
                "'{s}' has transactions but no declaration — nothing here can tell whether that is money you have or money you owe, so it is left out entirely"
            ));
        }
    }

    let mut out: Vec<AccountPosition> = Vec::new();
    for a in accounts {
        let declared = Currency::new(&a.currency).unwrap_or(Currency::USD);
        if declared != currency {
            problems.push(format!(
                "'{}' is in {} not {} — it is excluded rather than converted, because a rate is a decision and a net worth across currencies is not one number",
                a.id, a.currency, currency
            ));
            continue;
        }
        let Some(stated) = balances.iter().find(|b| b.account == a.id) else {
            problems.push(format!(
                "'{}' is declared but has no balance — its transactions cannot say what it holds, only how it moved",
                a.id
            ));
            continue;
        };
        if stated.as_of.as_str() > ledger.through() {
            problems.push(format!(
                "'{}' has a balance dated {}, past the {} the ledger actually covers — the transactions between them are not here to check it",
                a.id,
                stated.as_of,
                ledger.through()
            ));
        }

        // ONLY WHAT CAME AFTER. A transaction dated on or before the stated balance is already
        // inside that balance; applying it again double-counts, and the error is invisible because
        // the result is still a plausible number.
        let after: Vec<Money> = rows
            .iter()
            .filter(|t| t.account == a.id && t.date > stated.as_of)
            .map(|t| t.amount)
            .collect();
        let movement = sum(&after, currency).unwrap_or(money(0, currency));
        let balance = money(stated.balance.minor + movement.minor, currency);

        let owed_minor = if balance.minor < 0 { -balance.minor } else { 0 };
        let owed = (owed_minor > 0).then(|| money(owed_minor, currency));
        let credit_limit = a.credit_limit.map(|l| money(l, currency));
        let apr = apr_of(a);

        if a.kind == Kind::Credit && credit_limit.is_none() {
            problems.push(format!(
                "'{}' is a credit line with no limit — its utilisation is UNKNOWN, which is not the same as 0%",
                a.id
            ));
        }
        if a.kind.is_debt() && owed.is_some() && apr.is_none() {
            problems.push(format!(
                "'{}' owes {owed_minor} minor units at an unknown APR — the daily interest and weighted APR below both understate what this costs",
                a.id
            ));
        }

        out.push(AccountPosition {
            account: a.id.clone(),
            institution: a.institution.clone(),
            kind: a.kind,
            balance,
            as_of: ledger.through().to_string(),
            rolled_forward: after.len(),
            is_debt: a.kind.is_debt(),
            owed,
            credit_limit,
            available: credit_limit.map(|l| money(l.minor - owed_minor, currency)),
            utilisation: credit_limit
                .filter(|l| l.minor > 0)
                .map(|l| round3(owed_minor as f64 / l.minor as f64)),
            apr,
            daily_interest: match (apr, owed) {
                (Some(r), Some(o)) => Some(scale(o, r / 365.0, Rounding::HalfUp)),
                _ => None,
            },
            minimum_payment: a.minimum_payment.filter(|_| owed.is_some()).map(|m| money(m, currency)),
        });
    }

    let net_worth = sum(&out.iter().map(|a| a.balance).collect::<Vec<_>>(), currency).unwrap_or(money(0, currency));
    let liquid = sum(
        &out.iter().filter(|a| a.kind.is_liquid()).map(|a| a.balance).collect::<Vec<_>>(),
        currency,
    )
    .unwrap_or(money(0, currency));

    let debts: Vec<&AccountPosition> = out.iter().filter(|a| a.owed.is_some()).collect();
    let total_debt: i64 = debts.iter().map(|a| a.owed.unwrap().minor).sum();
    let rated: Vec<&&AccountPosition> = debts.iter().filter(|a| a.apr.is_some()).collect();
    let rated_total: i64 = rated.iter().map(|a| a.owed.unwrap().minor).sum();

    if ledger.unverified() {
        problems.push(format!("the ledger under this was NOT reconciled: {}", ledger.caveat().unwrap_or("no reason given")));
    }

    Position {
        as_of: ledger.through().to_string(),
        currency,
        net_worth,
        liquid,
        total_debt: money(total_debt, currency),
        daily_interest: money(debts.iter().filter_map(|a| a.daily_interest).map(|m| m.minor).sum(), currency),
        minimums_due: money(debts.iter().filter_map(|a| a.minimum_payment).map(|m| m.minor).sum(), currency),
        weighted_apr: (rated_total > 0).then(|| {
            let w: f64 = rated.iter().map(|a| a.owed.unwrap().minor as f64 * a.apr.unwrap()).sum();
            (w / rated_total as f64 * 10_000.0).round() / 10_000.0
        }),
        complete: problems.is_empty(),
        problems,
        provenance: format!("{} · position as of {}", ledger.provenance(), ledger.through()),
        accounts: out,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;
    use crate::reconcile::unverified_ledger;
    use crate::txn::Txn;

    // SYNTHETIC FIXTURES ONLY. No real balance or account number belongs in this repo.
    fn acct(id: &str, kind: Kind) -> Account {
        Account {
            id: id.into(),
            institution: format!("Example {id}"),
            kind,
            currency: "USD".into(),
            credit_limit: None,
            apr_bps: None,
            minimum_payment: None,
            statement_day: None,
            note: None,
        }
    }

    fn card() -> Account {
        Account { credit_limit: Some(600_000), apr_bps: Some(2499), minimum_payment: Some(9_000), ..acct("card", Kind::Credit) }
    }

    fn loan() -> Account {
        Account { apr_bps: Some(699), minimum_payment: Some(22_000), ..acct("loan", Kind::Loan) }
    }

    fn bal(account: &str, minor: i64) -> AccountBalance {
        AccountBalance { account: account.into(), as_of: "2026-06-01".into(), balance: usd(minor) }
    }

    fn tx(date: &str, desc: &str, minor: i64, account: &str) -> Txn {
        Txn { date: date.into(), description: desc.into(), amount: usd(minor), account: account.into() }
    }

    fn led(txns: &[Txn]) -> ReconciledLedger {
        unverified_ledger(txns, "2026-06-30", "synthetic").unwrap()
    }

    /// EVERY NUMBER BELOW CAME FROM RUNNING `@/features/finance/lib/position`, not from reading it.
    #[test]
    fn the_port_matches_the_typescript_number_for_number() {
        assert_eq!(from_statement_balance(Kind::Credit, usd(243_107)).minor, -243_107);
        assert_eq!(from_statement_balance(Kind::Credit, usd(-5_000)).minor, 5_000);
        assert_eq!(from_statement_balance(Kind::Checking, usd(120_000)).minor, 120_000);

        let p = position(
            &led(&[]),
            &[acct("checking", Kind::Checking), card()],
            &[bal("checking", 120_000), bal("card", -243_107)],
            Currency::USD,
        );
        assert_eq!(p.net_worth.minor, -123_107);
        assert_eq!(p.liquid.minor, 120_000);
        assert_eq!(p.total_debt.minor, 243_107);

        let p = position(
            &led(&[]),
            &[acct("checking", Kind::Checking), card(), loan()],
            &[bal("checking", 120_000), bal("card", -200_000), bal("loan", -800_000)],
            Currency::USD,
        );
        let c = p.accounts.iter().find(|a| a.account == "card").unwrap();
        assert_eq!(c.utilisation, Some(0.333));
        assert_eq!(c.available.unwrap().minor, 400_000);
        assert_eq!(c.daily_interest.unwrap().minor, 137);
        assert_eq!(p.weighted_apr, Some(0.1059));
        assert_eq!(p.minimums_due.minor, 31_000);
        assert_eq!(p.daily_interest.minor, 290);
        assert_eq!(annual_interest_cost(&p).minor, 105_850);
        assert_eq!(overall_utilisation(&p), Some(0.333));
        assert_eq!(by_cost(&p).iter().map(|a| a.account.as_str()).collect::<Vec<_>>(), ["card", "loan"]);
    }

    #[test]
    fn a_payment_from_chequing_to_a_card_moves_nothing() {
        // The proof the sign contract holds end to end. A model that reports an improvement in net
        // worth here is wrong in a way that feels like progress.
        let accounts = [acct("checking", Kind::Checking), card()];
        let balances = [bal("checking", 120_000), bal("card", -200_000)];
        let before = position(&led(&[]), &accounts, &balances, Currency::USD);
        let after = position(
            &led(&[tx("2026-06-10", "PAYMENT TO CARD", -30_000, "checking"), tx("2026-06-10", "PAYMENT RECEIVED", 30_000, "card")]),
            &accounts,
            &balances,
            Currency::USD,
        );
        assert_eq!(after.net_worth.minor, before.net_worth.minor);
        // Not a no-op though: liquidity fell and the debt shrank.
        assert_eq!(after.liquid.minor, 90_000);
        assert_eq!(after.total_debt.minor, 170_000);
    }

    #[test]
    fn only_what_came_after_the_stated_balance_is_applied() {
        // A transaction dated ON the balance date is already inside it. Applying it again
        // double-counts, and the result is still a plausible number.
        let p = position(
            &led(&[
                tx("2026-05-20", "BEFORE", -10_000, "checking"),
                tx("2026-06-01", "ON THE DATE", -5_000, "checking"),
                tx("2026-06-10", "AFTER", -2_500, "checking"),
            ]),
            &[acct("checking", Kind::Checking)],
            &[bal("checking", 120_000)],
            Currency::USD,
        );
        assert_eq!(p.accounts[0].rolled_forward, 1);
        assert_eq!(p.accounts[0].balance.minor, 117_500);
    }

    #[test]
    fn what_is_unknown_is_none_rather_than_zero() {
        // 0% utilised is an excellent score. Not knowing is not an excellent score.
        let no_limit = Account { credit_limit: None, ..card() };
        let p = position(&led(&[]), &[no_limit], &[bal("card", -200_000)], Currency::USD);
        assert_eq!(p.accounts[0].utilisation, None);
        assert_eq!(p.accounts[0].available, None);
        assert!(!p.complete);
        assert!(p.problems.iter().any(|x| x.contains("UNKNOWN")));

        let no_apr = Account { apr_bps: None, ..card() };
        let p = position(&led(&[]), &[no_apr], &[bal("card", -200_000)], Currency::USD);
        assert_eq!(p.accounts[0].daily_interest, None);
        assert_eq!(p.weighted_apr, None);
        assert!(p.problems.iter().any(|x| x.contains("understate")));
    }

    #[test]
    fn a_cleared_debt_owes_nothing_costs_nothing_and_is_not_due_a_minimum() {
        let p = position(&led(&[]), &[card()], &[bal("card", 0)], Currency::USD);
        assert_eq!(p.accounts[0].owed, None);
        assert_eq!(p.accounts[0].utilisation, Some(0.0));
        assert_eq!(p.minimums_due.minor, 0);
        assert_eq!(p.daily_interest.minor, 0);
        assert_eq!(p.total_debt.minor, 0);
    }

    #[test]
    fn an_undeclared_account_is_named_and_left_out_rather_than_given_an_invented_sign() {
        let p = position(
            &led(&[tx("2026-06-10", "MYSTERY", -30_000, "unknown-account")]),
            &[acct("checking", Kind::Checking)],
            &[bal("checking", 120_000)],
            Currency::USD,
        );
        assert!(!p.complete);
        assert!(p.problems.iter().any(|x| x.contains("'unknown-account'")));
        assert_eq!(p.net_worth.minor, 120_000);
    }

    #[test]
    fn another_currency_is_excluded_rather_than_converted() {
        let eur = Account { currency: "EUR".into(), ..acct("eu", Kind::Checking) };
        let p = position(
            &led(&[]),
            &[acct("checking", Kind::Checking), eur],
            &[bal("checking", 120_000), bal("eu", 90_000)],
            Currency::USD,
        );
        assert_eq!(p.accounts.len(), 1);
        assert_eq!(p.net_worth.minor, 120_000);
        assert!(p.problems.iter().any(|x| x.contains("not one number")));
    }

    #[test]
    fn an_investment_counts_toward_net_worth_but_never_toward_liquidity() {
        let p = position(
            &led(&[]),
            &[acct("checking", Kind::Checking), acct("broker", Kind::Investment)],
            &[bal("checking", 120_000), bal("broker", 4_000_000)],
            Currency::USD,
        );
        assert_eq!(p.net_worth.minor, 4_120_000);
        assert_eq!(p.liquid.minor, 120_000);
    }

    #[test]
    fn an_unreconciled_ledger_carries_its_caveat_forward_instead_of_being_laundered() {
        let l = unverified_ledger(&[], "2026-06-30", "Chase export has no opening balance").unwrap();
        let p = position(&l, &[acct("checking", Kind::Checking)], &[bal("checking", 120_000)], Currency::USD);
        assert!(!p.complete);
        assert!(p.problems.iter().any(|x| x.contains("Chase export has no opening balance")));
        assert!(p.provenance.starts_with("UNVERIFIED"));
    }

    #[test]
    fn the_weighted_apr_weights_by_balance_not_by_account_count() {
        // $8,000 at 6.99% and $2,000 at 24.99% is not a 15.99% problem, and averaging the rates
        // would send somebody at the wrong debt first.
        let p = position(
            &led(&[]),
            &[card(), loan()],
            &[bal("card", -200_000), bal("loan", -800_000)],
            Currency::USD,
        );
        let w = p.weighted_apr.unwrap();
        assert!(w < (0.2499 + 0.0699) / 2.0, "weighted {w} should be below the plain mean");
        assert_eq!(w, 0.1059);
    }
}
